#include "scarlett_cpu64.hpp"
#include <cassert>
using namespace genesis;
int main(){GuestMemory64 m; ScarlettImports64 i; assert(i.install(m)); unsetenv("ALIEN_XBOX_MEMORY_EXPERIMENT"); assert(!i.registerImport("xmem.dll","XMemVirtualAlloc")); setenv("ALIEN_XBOX_MEMORY_EXPERIMENT","1",1); auto c=i.registerImport("d3d12_xs.dll","D3D12ConfigureVirtualMemoryX"),a=i.registerImport("xmem.dll","XMemVirtualAlloc"); assert(c&&a); uint64_t r=0; assert(i.dispatch(a,m,0,r,24ULL<<30,0x20402000,0x21,4)&&!r); assert(m.map(0x10000,4096,3)==GuestMemory64::Fault::none); std::array<uint8_t,8>b{0,0,0,0,4,0,0,0}; assert(m.write(0x10000,b)==GuestMemory64::Fault::none); assert(i.dispatch(c,m,0x10000,r)&&!r); assert(i.dispatch(a,m,0,r,24ULL<<30,0x20402000,0x21,5)&&!r); assert(i.dispatch(a,m,0,r,24ULL<<30,0x20402000,0x21,4)&&r); auto first=r; assert(i.dispatch(a,m,0,r,24ULL<<30,0x20402000,3,0x801)&&r==first+(24ULL<<30)); assert(m.sparseCommittedPages()==0); assert(i.dispatch(a,m,0,r,0x49400000,0x20003000,0x183,0x22005)&&!r); assert(i.dispatch(a,m,0,r,0x49400000,0x20003000,0x183,0x22004)&&r==first+(48ULL<<30)); assert(m.sparseCommittedPages()==0); assert(m.write(r,b)==GuestMemory64::Fault::none); std::array<uint8_t,8> out{}; assert(m.read(r,out)==GuestMemory64::Fault::none && out==b); assert(m.sparseCommittedPages()==1); auto third=r; assert(i.dispatch(a,m,0,r,0x89700000,0x20003000,0x283,0x2405)&&!r); assert(i.dispatch(a,m,0,r,0x89700000,0x20003000,0x283,0x2404)&&r==third+0x49400000); assert(m.sparseCommittedPages()==1); assert(m.read(r,out)==GuestMemory64::Fault::none); assert((out==std::array<uint8_t,8>{})); assert(m.write(r+0x89700000-8,b)==GuestMemory64::Fault::none); assert(m.read(r+0x89700000-8,out)==GuestMemory64::Fault::none && out==b); assert(m.sparseCommittedPages()==2); puts("V48 sparse allocation tests passed");}
